mapper.select:
SELECT caller_client_id, request_id, identity_id, status, challenge_id, challenge_expires_at, completed_at
FROM iam_password_setup_deliveries
WHERE caller_client_id = #{callerClientId} AND request_id = #{requestId}

mapper.update:
UPDATE iam_password_setup_deliveries
SET status = 'PASSWORD_READY', challenge_id = NULL, challenge_expires_at = NULL,
    completed_at = #{completedAt}
WHERE caller_client_id = #{callerClientId}
  AND request_id = #{requestId}
  AND identity_id = #{identityId}
  AND status = 'PENDING'

UPDATE iam_password_setup_deliveries
SET status = 'DELIVERED', completed_at = #{deliveredAt}
WHERE caller_client_id = #{callerClientId}
  AND request_id = #{requestId}
  AND challenge_id = #{challengeId}
  AND status = 'PENDING'
